Image*
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  MngInfo *mng_info;
  FILE *file_handle;
  size_t file_size;
  unsigned char signature[16];

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  file_handle = fopen(image_info->filename, "rb");
  if (file_handle == (FILE *) NULL)
  {
    (void) ThrowMagickException(exception, GetMagickModule(), FileOpenError,
      "UnableToOpenFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (fread(signature, 1, sizeof(signature), file_handle) != sizeof(signature))
  {
    (void) fclose(file_handle);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "InsufficientImageDataInFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  if (memcmp(signature, "\213JNG", 4) != 0)
  {
    (void) fclose(file_handle);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "NotJNGFile", "%s", image_info->filename);
    return (Image *) NULL;
  }

  fseek(file_handle, 0, SEEK_END);
  file_size = ftell(file_handle);
  fseek(file_handle, 0, SEEK_SET);

  if (file_size <= 0)
  {
    (void) fclose(file_handle);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "InvalidFileSize", "%s", image_info->filename);
    return (Image *) NULL;
  }

  mng_info = (MngInfo *) AcquireMemory(sizeof(*mng_info));
  if (mng_info == (MngInfo *) NULL)
  {
    (void) fclose(file_handle);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "UnableToAllocateMemory", "%s", image_info->filename);
    return (Image *) NULL;
  }

  image = (Image *) AcquireMemory(sizeof(*image));
  if (image == (Image *) NULL)
  {
    (void) fclose(file_handle);
    RelinquishMemory(mng_info);
    (void) ThrowMagickException(exception, GetMagickModule(), ResourceLimitError,
      "UnableToAllocateMemory", "%s", image_info->filename);
    return (Image *) NULL;
  }

  /* Read image data from the JNG file into the Image structure. */
  (void) ReadImage(file_handle, image, mng_info, exception);

  (void) fclose(file_handle);

  if (image->columns == 0 || image->rows == 0)
  {
    DestroyImage(image);
    (void) ThrowMagickException(exception, GetMagickModule(), CorruptImageError,
      "InvalidImageDimensions", "%s", image_info->filename);
    return (Image *) NULL;
  }

  return image;
}

Image*
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  FILE *file;

  if ((file = fopen(image_info->filename, "rb")) == NULL)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenFile, image_info->filename);
    return (Image *) NULL;
  }

  {
    unsigned char signature[JNG_HEADER_SIZE] = {0x00, 0x00, 0x00, 0x0d, 0x4a, 0x58, 0x58, 0x20};
    if (fread(signature, sizeof(*signature), JNG_HEADER_SIZE, file) != JNG_HEADER_SIZE)
    {
      fclose(file);
      ThrowFileException(exception, CorruptImageError, UnexpectedEndOfFile, image_info->filename);
      return (Image *) NULL;
    }

    if (memcmp(signature, "\x89JNG", 4) != 0)
    {
      fclose(file);
      ThrowFileException(exception, CorruptImageError, InvalidImageFormat, image_info->filename);
      return (Image *) NULL;
    }
  }

  if (fseek(file, 0, SEEK_END) != 0)
  {
    fclose(file);
    ThrowFileException(exception, FileOpenError, UnableToSeekInFile, image_info->filename);
    return (Image *) NULL;
  }

  if (ftell(file) <= 0)
  {
    fclose(file);
    ThrowFileException(exception, CorruptImageError, InvalidFileSize, image_info->filename);
    return (Image *) NULL;
  }

  rewind(file);

  image = AcquireImage(image_info, exception);

  if (image->columns == 0 || image->rows == 0)
  {
    fclose(file);
    ThrowMagickException(exception, MagickCoder, delegate_failed, "InvalidImageDimensions", "`%s'", image_info->filename);
    image = DestroyImageList(image);
    return (Image *) NULL;
  }

  if ((image->storage_class != DirectClass) && (image->colors > 256))
  {
    fclose(file);
    ThrowMagickException(exception, MagickCoder, InvalidImage, "InvalidImageDepth", "`%s'", image_info->filename);
    image = DestroyImageList(image);
    return (Image *) NULL;
  }

  {
    MngInfo *mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
    if (mng_info == NULL)
    {
      fclose(file);
      ThrowMagickException(exception, MagickCoder, ResourceLimitError, "UnableToAllocateMemory", "`%s'", image_info->filename);
      image = DestroyImageList(image);
      return (Image *) NULL;
    }

    memset(mng_info, 0, sizeof(*mng_info));
    image->mng_info = mng_info;
  }

  {
    size_t read_size;
    unsigned char *buffer = (unsigned char *) AcquireMagickMemory(image->columns * image->rows * sizeof(*buffer));
    if (buffer == NULL)
    {
      fclose(file);
      ThrowMagickException(exception, MagickCoder, ResourceLimitError, "UnableToAllocateMemory", "`%s'", image_info->filename);
      image = DestroyImageList(image);
      return (Image *) NULL;
    }

    if ((read_size = fread(buffer, sizeof(*buffer), image->columns * image->rows, file)) != image->columns * image->rows)
    {
      fclose(file);
      RelinquishMagickMemory(buffer);
      if (read_size == 0)
      {
        ThrowFileException(exception, CorruptImageError, UnexpectedEndOfFile, image_info->filename);
      }
      else
      {
        ThrowMagickException(exception, MagickCoder, CorruptImageError, "InvalidImageFormat", "`%s'", image_info->filename);
      }
      image = DestroyImageList(image);
      return (Image *) NULL;
    }

    memcpy(image->pixels, buffer, image->columns * image->rows * sizeof(*buffer));
    RelinquishMagickMemory(buffer);
  }

  fclose(file);
  return image;
}

Image *
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  MngInfo *mng_info;
  FILE *file;
  MagickSizeType
    file_size;
  size_t
    count;
  unsigned char
    signature[16];

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL)
    return((Image *) NULL);

  file = fopen(image->filename, "rb");
  if (file == (FILE *) NULL)
  {
    ThrowFileException(exception, FileOpenError, UnableToOpenFile, image->filename);
    return((Image *) NULL);
  }

  count = fread(signature, 1, 8, file);
  if ((count != 8) || memcmp(signature, "\212PNG\r\n\n\n", 8))
  {
    if (fseek(file, 0, SEEK_END))
    {
      fclose(file);
      return((Image *) NULL);
    }

    file_size = (MagickSizeType) ftello(file);
    if (file_size < 0)
    {
      fclose(file);
      return((Image *) NULL);
    }

    if (fseek(file, 0, SEEK_SET))
    {
      fclose(file);
      return((Image *) NULL);
    }

    mng_info = (MngInfo *) AcquireMagickMemory(sizeof(*mng_info));
    if (mng_info == (MngInfo *) NULL)
    {
      fclose(file);
      return((Image *) NULL);
    }

    (void) memset(mng_info, 0, sizeof(*mng_info));

    image->depth = 8;
    image->columns = (size_t) 1;
    image->rows = (size_t) 1;
  }

  return image;
}

Image*
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image = NULL;
  FILE *file = NULL;
  unsigned char signature[16];
  size_t bytes_read;
  MagickSizeType file_size;

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  file = fopen(image_info->filename, "rb");
  if (file == NULL)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenImage, image_info->filename);
    return NULL;
  }

  bytes_read = fread(signature, sizeof(unsigned char), 4, file);
  if (bytes_read != 4)
  {
    ThrowFileException(exception, CorruptImageError, UnexpectedEndOfFile, image_info->filename);
    fclose(file);
    return NULL;
  }

  if (signature[0] != 0x89 || memcmp(signature + 1, "JNG", 3) != 0)
  {
    ThrowMagickException(exception, MagickPath, CorruptImageError, "NotJNGFormat", "`%s' is not a JNG image", image_info->filename);
    fclose(file);
    return NULL;
  }

  // Seek to the end of the file to get its size
  if (fseek(file, 0, SEEK_END) != 0)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenImage, image_info->filename);
    fclose(file);
    return NULL;
  }

  file_size = ftell(file);
  if (file_size == -1L)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenImage, image_info->filename);
    fclose(file);
    return NULL;
  }

  if (fseek(file, 0, SEEK_SET) != 0)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenImage, image_info->filename);
    fclose(file);
    return NULL;
  }

  image = AcquireImage(image_info, exception);
  if (image == (Image *) NULL)
  {
    fclose(file);
    return NULL;
  }

  // Allocate MngInfo structure
  MngInfo *mng_info = (MngInfo *) AcquireMagickMemory(sizeof(MngInfo));
  if (mng_info == (MngInfo *) NULL)
  {
    fclose(file);
    DestroyImageList(image);
    return NULL;
  }

  // Initialize mng_info structure
  (void) ResetMagickMemory(mng_info, 0, sizeof(MngInfo));
  mng_info->signature = signature;

  image->mng_info = mng_info;

  if (ReadImageFile(file, image, exception) == MagickFalse)
  {
    fclose(file);
    DestroyImageList(image);
    return NULL;
  }

  if (image->columns == 0 || image->rows == 0)
  {
    ThrowMagickException(exception, MagickPath, ImageError, "InvalidImageGeometry", "Image has invalid geometry");
    fclose(file);
    DestroyImageList(image);
    return NULL;
  }

  fclose(file);
  return image;
}

Image*
ReadJNGImage(const ImageInfo *image_info, ExceptionInfo *exception)
{
  Image *image;
  MngInfo *mng_info;
  FILE *file;
  size_t file_size;
  unsigned char signature[16];

  assert(image_info != (ImageInfo *) NULL);
  assert(exception != (ExceptionInfo *) NULL);

  file = fopen(image_info->filename, "rb");
  if (file == (FILE *) NULL)
  {
    ThrowFileException(exception, FileOpenError, CannotOpenImage, image_info->filename);
    return((Image *) NULL);
  }

  file_size = fread(signature, 1, sizeof(signature), file);
  if (file_size != sizeof(signature))
  {
    fclose(file);
    ThrowFileException(exception, CorruptImageError, PrematureEndOfFile, image_info->filename);
    return((Image *) NULL);
  }

  if (memcmp(signature, "\213PNG\r\n\032\n", 8) != 0)
  {
    fclose(file);
    Throw(exception, CorruptImageError, InvalidSignature, image_info->filename);
    return((Image *) NULL);
  }

  mng_info = (MngInfo *) AcquireMemory(sizeof(MngInfo));
  if (mng_info == (MngInfo *) NULL)
  {
    fclose(file);
    ThrowMemoryException(exception);
    return((Image *) NULL);
  }

  mng_info->signature = 0;

  fseek(file, 0, SEEK_SET);
  image = CloneImageInfoToImage(image_info, exception);
  if (image == (Image *) NULL)
  {
    fclose(file);
    RelinquishMemory(mng_info);
    return((Image *) NULL);
  }

  if ((image->columns == 0) || (image->rows == 0))
  {
    fclose(file);
    RelinquishMemory(mng_info);
    Throw(exception, OptionError, InvalidImageGeometry, image_info->filename);
    return((Image *) NULL);
  }

  if (!ReadImageFile(image, file, exception))
  {
    fclose(file);
    RelinquishMemory(mng_info);
    return((Image *) NULL);
  }

  image->mng_info = mng_info;
  fclose(file);

  return(image);
}
